function solve(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const inA = Array.from({ length: rows }, () => new Array(cols).fill(false));
  let si = -1;
  let sj = -1;
  for (let i = 0; i < rows && si === -1; i++) {
    for (let j = 0; j < cols; j++) {
      if (grid[i][j] === 1) {
        si = i;
        sj = j;
        break;
      }
    }
  }
  if (si === -1) return -1;
  const stack = [[si, sj]];
  inA[si][sj] = true;
  while (stack.length > 0) {
    const cell = stack.pop();
    for (const d of dirs) {
      const x = cell[0] + d[0];
      const y = cell[1] + d[1];
      if (x >= 0 && y >= 0 && x < rows && y < cols && grid[x][y] === 1 && !inA[x][y]) {
        inA[x][y] = true;
        stack.push([x, y]);
      }
    }
  }
  let best = Infinity;
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      if (!inA[i][j]) continue;
      const dist = Array.from({ length: rows }, () => new Array(cols).fill(-1));
      dist[i][j] = 0;
      const queue = [[i, j]];
      let head = 0;
      while (head < queue.length) {
        const cell = queue[head];
        head++;
        if (!inA[cell[0]][cell[1]] && grid[cell[0]][cell[1]] === 1) {
          if (dist[cell[0]][cell[1]] - 1 < best) best = dist[cell[0]][cell[1]] - 1;
          break;
        }
        for (const d of dirs) {
          const x = cell[0] + d[0];
          const y = cell[1] + d[1];
          if (x >= 0 && y >= 0 && x < rows && y < cols && dist[x][y] === -1) {
            dist[x][y] = dist[cell[0]][cell[1]] + 1;
            queue.push([x, y]);
          }
        }
      }
    }
  }
  return best === Infinity ? -1 : best;
}

